/**
 * Initialize sidebar navigation
 */
function initializeSidebarNavigation() {
    const sidebarLinks = document.querySelectorAll('.sidebar-link');

    sidebarLinks.forEach(link => {
        link.addEventListener('click', function(event) {
            event.preventDefault();

            // Remove active class from all links
            sidebarLinks.forEach(l => {
                l.classList.remove('active');
                l.removeAttribute('aria-current');
            });

            // Add active class to clicked link
            this.classList.add('active');
            this.setAttribute('aria-current', 'page');

            // Get the page name from data attribute
            const page = this.getAttribute('data-page');
            console.log(`Navigated to: ${page}`);

            // Close sidebar on mobile after selection
            if (window.innerWidth <= 768) {
                const sidebar = document.getElementById('sidebar');
                sidebar.classList.remove('show');
            }

            // Load page content
            loadPageContent(page);
        });
    });
}


/**
 * Initialize sidebar toggle button
 */
function initializeSidebarToggle() {
    const sidebarToggle = document.getElementById('sidebarToggle');
    const sidebar = document.getElementById('sidebar');

    if (sidebarToggle && sidebar) {
        sidebarToggle.addEventListener('click', function() {
            sidebar.classList.toggle('show');
            sidebar.classList.toggle('collapsed');
        });

        // Close sidebar when clicking outside on mobile
        document.addEventListener('click', function(event) {
            if (window.innerWidth <= 768) {
                const isClickInsideSidebar = sidebar.contains(event.target);
                const isClickOnToggle = sidebarToggle.contains(event.target);

                if (!isClickInsideSidebar && !isClickOnToggle && sidebar.classList.contains('show')) {
                    sidebar.classList.remove('show');
                }
            }
        });
    }
}


/**
 * Load content based on selected menu item
 */
function loadPageContent(page) {
    console.log(`Loading content for: ${page}`);

    // Hide all page content sections
    const pages = document.querySelectorAll('.page-content');
    pages.forEach(p => {
        p.classList.remove('active');
    });

    // Show the selected page
    const selectedPage = document.getElementById(`page-${page}`);
    if (selectedPage) {
        selectedPage.classList.add('active');

        // Smooth scroll to top of content
        window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
        console.error(`Page not found: page-${page}`);
    }

    // Optional: Load dynamic data for the page
    // Example: loadPageData(page);
}


